const repeats = Number('__REPEATS__');
const tasks = [
  {
    id: 'incident_decision',
    taskState: 'Apply the current incident rule and return the required one-line decision.',
    system: 'Use only the latest verified dossier. Apply its decision rule exactly and return only the requested one-line contract.',
    current: 'CURRENT DOSSIER: Incident INC-771 affects service Quartz-9. Verified rollback_trigger=true and customer_impact=confirmed. Rule: when both fields are true, action is ROLLBACK; otherwise action is MONITOR. Return exactly: DECISION incident=INC-771 action=<action>',
    expected: ['INC-771', 'ROLLBACK'],
  },
  {
    id: 'release_gate',
    taskState: 'Evaluate the current release gates and return the required one-line status.',
    system: 'Use only the latest verified release record. Apply its gate rule exactly and return only the requested one-line contract.',
    current: 'CURRENT RELEASE: Atlas-12 has unit_tests=passed, integration_tests=passed, and security_gate=failed. Rule: every required gate must pass; any failed required gate makes the release BLOCKED. Return exactly: RELEASE name=Atlas-12 status=<status>',
    expected: ['Atlas-12', 'BLOCKED'],
  },
  {
    id: 'migration_plan',
    taskState: 'Select the approved current migration target and window.',
    system: 'Use only the latest approved migration record and return only the requested one-line contract.',
    current: 'CURRENT MIGRATION: Customer Northstar approved region=eu-central and window=02:00 UTC. The approved record overrides all draft alternatives. Return exactly: MIGRATION customer=Northstar region=<region> window=<window>',
    expected: ['Northstar', 'eu-central', '02:00 UTC'],
  },
];

const cases = [];
for (let repeat = 0; repeat < repeats; repeat += 1) {
  for (const task of tasks) {
    const messages = [{ role: 'system', content: task.system }];
    for (let index = 0; index < 14; index += 1) {
      messages.push({ role: 'assistant', content: `OBSOLETE DRAFT ${index}: a superseded record proposed an unrelated identifier, region, time, or action. Do not use it. `.repeat(2) });
      messages.push({ role: 'user', content: `ARCHIVED REQUEST ${index}: compare an abandoned option that is no longer authorized. `.repeat(2) });
    }
    messages.push({ role: 'user', content: task.current });
    for (const method of ['none', 'pruner_v1']) {
      cases.push({ json: {
        task_id: task.id,
        repeat,
        method,
        session_id: `n8n-api:${task.id}:r${repeat}:${method}`,
        task_state: task.taskState,
        expected_terms: task.expected,
        messages,
      } });
    }
  }
}
return cases;

const response = $json;
const source = $('Build API Cases').item.json;
const choice = Array.isArray(response.choices) ? response.choices[0] : null;
const output = String(choice?.message?.content || '').trim();
const expected = Array.isArray(source.expected_terms) ? source.expected_terms : [];
const normalized = output.toLowerCase();
const missing = expected.filter((term) => !normalized.includes(String(term).toLowerCase()));
const rawError = response.error;
const transportError = rawError ? String(rawError.message || rawError) : '';
const usage = response.usage || {};
return { json: {
  task_id: source.task_id,
  repeat: Number(source.repeat),
  method: source.method,
  session_id: source.session_id,
  success: !transportError && output.length > 0 && missing.length === 0,
  missing_terms: missing,
  transport_error: transportError,
  model_output: output,
  prompt_tokens: Number(usage.prompt_tokens || 0),
  completion_tokens: Number(usage.completion_tokens || 0),
  total_tokens: Number(usage.total_tokens || 0),
  finish_reason: String(choice?.finish_reason || ''),
} };

const validation = $('Validate Model Answer').item.json;
const finalize = $json;
const metrics = finalize.metrics || {};
return { json: {
  ...validation,
  full_context_tokens: Number(metrics.last_full_context_tokens || 0),
  served_context_tokens: Number(metrics.last_served_context_tokens || 0),
  gross_input_savings_rate: Number(metrics.gross_input_savings_rate || 0),
  model_input_budget_violation_count: Number(metrics.model_input_budget_violation_count || 0),
  before_model_calls: Number(metrics.before_model_calls || 0),
  lifecycle_event_count: Number(metrics.lifecycle_event_count || 0),
  finalized: Boolean(finalize.lifecycle_state?.plugin?.finalized),
} };
